<template><label class="ui-slider"><span v-if="label">{{ label }}</span><input type="range" :min="min" :max="max" :step="step" :value="modelValue" :disabled="disabled" @input="emit('update:modelValue',Number(($event.target as HTMLInputElement).value))"><output class="ui-numeric">{{ modelValue }}{{ suffix }}</output></label></template>
<script setup lang="ts">withDefaults(defineProps<{modelValue:number;label?:string;min?:number;max?:number;step?:number;suffix?:string;disabled?:boolean}>(),{min:0,max:100,step:1,suffix:''});const emit=defineEmits<{'update:modelValue':[number]}>();</script>
<style scoped>.ui-slider{display:grid;grid-template-columns:auto minmax(100px,1fr) auto;align-items:center;gap:10px;color:var(--ui-text-muted);font-size:13px}.ui-slider input{height:4px;accent-color:var(--ui-text)}.ui-slider output{min-width:36px;color:var(--ui-text);text-align:right}</style>
